[patterns/application/api-microservices/PTN-APP-API-016-pagination-pattern.md#5-hateoas-link-generation]

#### 5. HATEOAS Link Generation

**Link Generation Logic:**

```csharp
public class PaginationLinkGenerator
{
    public PaginationLinks GenerateLinks(
        string baseUrl,
        int currentPage,
        int pageSize,
        long totalRecords,
        string cursor = null)
    {
        var links = new PaginationLinks
        {
            Self = BuildLink(baseUrl, currentPage, pageSize, cursor),
            First = BuildLink(baseUrl, 1, pageSize)
        };

        if (currentPage > 1)
        {
            links.Previous = BuildLink(baseUrl, currentPage - 1, pageSize);
        }

        var totalPages = (int)Math.Ceiling((double)totalRecords / pageSize);

        if (currentPage < totalPages)
        {
            links.Next = BuildLink(baseUrl, currentPage + 1, pageSize);
            links.Last = BuildLink(baseUrl, totalPages, pageSize);
        }

        return links;
    }

    private LinkObject BuildLink(string baseUrl, int page, int pageSize, string cursor = null)
    {
        var queryParams = cursor != null
            ? $"?cursor={Uri.EscapeDataString(cursor)}&pageSize={pageSize}"
            : $"?page={page}&pageSize={pageSize}";

        return new LinkObject
        {
            Href = $"{baseUrl}{queryParams}"
        };
    }
}
```

**Cursor-Based Link Example:**

```json
{
  "_links": {
    "self": {
      "href": "/api/v1/claims?cursor=eyJsYXN0SWQi...&pageSize=50"
    },
    "first": {
      "href": "/api/v1/claims?pageSize=50"
    },
    "next": {
      "href": "/api/v1/claims?cursor=eyJuZXh0SWQi...&pageSize=50"
    }
  }
}
```

**Note**: Cursor mode omits `last` and `previous` links (no random access).

