[patterns/application/api-microservices/PTN-APP-API-016-pagination-pattern.md#phase-1-basic-offset-pagination]

#### Phase 1: Basic Offset Pagination

**Step 1: Define Request/Response Models**

```csharp
// PaginationRequest.cs
public class PaginationRequest
{
    private int _page = 1;
    private int _pageSize = 50;

    [FromQuery(Name = "page")]
    [Range(1, int.MaxValue, ErrorMessage = "Page must be at least 1")]
    public int Page
    {
        get => _page;
        set => _page = value < 1 ? 1 : value;
    }

    [FromQuery(Name = "pageSize")]
    [Range(1, 500, ErrorMessage = "PageSize must be between 1 and 500")]
    public int PageSize
    {
        get => _pageSize;
        set => _pageSize = value < 1 ? 1 : value > 500 ? 500 : value;
    }

    [FromQuery(Name = "sortBy")]
    public string? SortBy { get; set; }

    [FromQuery(Name = "sortOrder")]
    [RegularExpression("^(asc|desc)$", ErrorMessage = "SortOrder must be 'asc' or 'desc'")]
    public string SortOrder { get; set; } = "desc";

    public int Skip => (Page - 1) * PageSize;
}

// PaginatedResponse.cs
public class PaginatedResponse<T>
{
    [JsonPropertyName("items")]
    public List<T> Items { get; set; } = new();

    [JsonPropertyName("pagination")]
    public PaginationMetadata Pagination { get; set; } = new();

    [JsonPropertyName("_links")]
    public PaginationLinks Links { get; set; } = new();

    [JsonPropertyName("meta")]
    public ResponseMetadata Meta { get; set; } = new();
}

public class PaginationMetadata
{
    [JsonPropertyName("page")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public int? Page { get; set; }

    [JsonPropertyName("pageSize")]
    public int PageSize { get; set; }

    [JsonPropertyName("totalRecords")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? TotalRecords { get; set; }

    [JsonPropertyName("totalPages")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public int? TotalPages { get; set; }

    [JsonPropertyName("hasMore")]
    public bool HasMore { get; set; }

    [JsonPropertyName("cursor")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Cursor { get; set; }
}

public class PaginationLinks
{
    [JsonPropertyName("self")]
    public LinkObject Self { get; set; } = new();

    [JsonPropertyName("first")]
    public LinkObject First { get; set; } = new();

    [JsonPropertyName("last")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public LinkObject? Last { get; set; }

    [JsonPropertyName("next")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public LinkObject? Next { get; set; }

    [JsonPropertyName("previous")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public LinkObject? Previous { get; set; }
}

public class LinkObject
{
    [JsonPropertyName("href")]
    public string Href { get; set; } = string.Empty;
}
```

**Step 2: Implement Offset-Based Repository Method**

```csharp
// IClaimRepository.cs
public interface IClaimRepository
{
    Task<(List<ClaimDto> Items, long TotalCount)> GetClaimsAsync(
        string providerId,
        PaginationRequest pagination,
        CancellationToken cancellationToken = default);
}

// ClaimRepository.cs (Entity Framework Core)
public class ClaimRepository : IClaimRepository
{
    private readonly ApplicationDbContext _context;

    public ClaimRepository(ApplicationDbContext context)
    {
        _context = context;
    }

    public async Task<(List<ClaimDto> Items, long TotalCount)> GetClaimsAsync(
        string providerId,
        PaginationRequest pagination,
        CancellationToken cancellationToken = default)
    {
        var query = _context.Claims
            .Where(c => c.ProviderId == providerId)
            .AsNoTracking();

        // Get total count (consider caching for expensive queries)
        var totalCount = await query.CountAsync(cancellationToken);

        // Apply sorting
        query = pagination.SortOrder.ToLower() == "asc"
            ? query.OrderBy(c => c.SubmittedDate).ThenBy(c => c.ClaimId)
            : query.OrderByDescending(c => c.SubmittedDate).ThenByDescending(c => c.ClaimId);

        // Apply pagination
        var items = await query
            .Skip(pagination.Skip)
            .Take(pagination.PageSize)
            .Select(c => new ClaimDto
            {
                ClaimId = c.ClaimId,
                ProviderId = c.ProviderId,
                MemberId = c.MemberId,
                SubmittedDate = c.SubmittedDate,
                Amount = c.Amount,
                Status = c.Status
            })
            .ToListAsync(cancellationToken);

        return (items, totalCount);
    }
}

// Generated SQL (optimized with index)
/*
SELECT [c].[ClaimId], [c].[ProviderId], [c].[MemberId], [c].[SubmittedDate], [c].[Amount], [c].[Status]
FROM [Claims] AS [c]
WHERE [c].[ProviderId] = @__providerId_0
ORDER BY [c].[SubmittedDate] DESC, [c].[ClaimId] DESC
OFFSET @__p_0 ROWS FETCH NEXT @__p_1 ROWS ONLY

-- With covering index IX_Claims_Pagination, this query is efficient for small offsets
*/
```

**Step 3: Implement Controller Action**

```csharp
// ClaimsController.cs
[ApiController]
[Route("api/v1/[controller]")]
public class ClaimsController : ControllerBase
{
    private readonly IClaimRepository _repository;
    private readonly IPaginationLinkGenerator _linkGenerator;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(
        IClaimRepository repository,
        IPaginationLinkGenerator linkGenerator,
        ILogger<ClaimsController> logger)
    {
        _repository = repository;
        _linkGenerator = linkGenerator;
        _logger = logger;
    }

    /// <summary>
    /// Get claims for a provider with pagination
    /// </summary>
    /// <param name="providerId">Provider NPI or ID</param>
    /// <param name="pagination">Pagination parameters</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>Paginated list of claims</returns>
    [HttpGet]
    [ProducesResponseType(typeof(PaginatedResponse<ClaimDto>), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ErrorResponse), StatusCodes.Status400BadRequest)]
    [ProducesResponseType(typeof(ErrorResponse), StatusCodes.Status500InternalServerError)]
    public async Task<ActionResult<PaginatedResponse<ClaimDto>>> GetClaims(
        [FromQuery, Required] string providerId,
        [FromQuery] PaginationRequest pagination,
        CancellationToken cancellationToken)
    {
        try
        {
            // Fetch data
            var (items, totalCount) = await _repository.GetClaimsAsync(
                providerId,
                pagination,
                cancellationToken);

            // Build response envelope
            var response = new PaginatedResponse<ClaimDto>
            {
                Items = items,
                Pagination = new PaginationMetadata
                {
                    Page = pagination.Page,
                    PageSize = pagination.PageSize,
                    TotalRecords = totalCount,
                    TotalPages = (int)Math.Ceiling((double)totalCount / pagination.PageSize),
                    HasMore = (pagination.Page * pagination.PageSize) < totalCount
                },
                Links = _linkGenerator.GenerateLinks(
                    Request.Path,
                    Request.QueryString.ToString(),
                    pagination.Page,
                    pagination.PageSize,
                    totalCount),
                Meta = new ResponseMetadata
                {
                    RequestId = Activity.Current?.Id ?? HttpContext.TraceIdentifier,
                    Timestamp = DateTime.UtcNow,
                    ApiVersion = "v1"
                }
            };

            _logger.LogInformation(
                "Retrieved {Count} claims for provider {ProviderId}, page {Page} of {TotalPages}",
                items.Count, providerId, pagination.Page, response.Pagination.TotalPages);

            return Ok(response);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error retrieving claims for provider {ProviderId}", providerId);
            return StatusCode(500, new ErrorResponse
            {
                Error = new ErrorDetail
                {
                    Code = "CLAIMS_RETRIEVAL_ERROR",
                    Message = "An error occurred while retrieving claims",
                    RequestId = HttpContext.TraceIdentifier
                }
            });
        }
    }
}
```

**Step 4: Implement Link Generator**

```csharp
// PaginationLinkGenerator.cs
public interface IPaginationLinkGenerator
{
    PaginationLinks GenerateLinks(
        string path,
        string queryString,
        int currentPage,
        int pageSize,
        long totalRecords);
}

public class PaginationLinkGenerator : IPaginationLinkGenerator
{
    private readonly IHttpContextAccessor _httpContextAccessor;

    public PaginationLinkGenerator(IHttpContextAccessor httpContextAccessor)
    {
        _httpContextAccessor = httpContextAccessor;
    }

    public PaginationLinks GenerateLinks(
        string path,
        string queryString,
        int currentPage,
        int pageSize,
        long totalRecords)
    {
        var request = _httpContextAccessor.HttpContext?.Request;
        var baseUrl = $"{request?.Scheme}://{request?.Host}{path}";

        // Parse existing query string
        var queryParams = HttpUtility.ParseQueryString(queryString.TrimStart('?'));

        var totalPages = (int)Math.Ceiling((double)totalRecords / pageSize);

        var links = new PaginationLinks
        {
            Self = BuildLink(baseUrl, queryParams, currentPage, pageSize),
            First = BuildLink(baseUrl, queryParams, 1, pageSize)
        };

        if (currentPage > 1)
        {
            links.Previous = BuildLink(baseUrl, queryParams, currentPage - 1, pageSize);
        }

        if (currentPage < totalPages)
        {
            links.Next = BuildLink(baseUrl, queryParams, currentPage + 1, pageSize);
            links.Last = BuildLink(baseUrl, queryParams, totalPages, pageSize);
        }

        return links;
    }

    private LinkObject BuildLink(
        string baseUrl,
        NameValueCollection queryParams,
        int page,
        int pageSize)
    {
        var newParams = new NameValueCollection(queryParams);
        newParams["page"] = page.ToString();
        newParams["pageSize"] = pageSize.ToString();

        var queryString = string.Join("&",
            newParams.AllKeys.Select(key => $"{key}={Uri.EscapeDataString(newParams[key])}"));

        return new LinkObject { Href = $"{baseUrl}?{queryString}" };
    }
}
```

