#### Phase 2: Add Cursor-Based Pagination

**Step 1: Define Cursor Models**

```csharp
// CursorToken.cs
public class CursorToken
{
    [JsonPropertyName("lastId")]
    public long LastId { get; set; }

    [JsonPropertyName("lastValue")]
    public string? LastValue { get; set; }

    [JsonPropertyName("sortBy")]
    public string SortBy { get; set; } = "createdDate";

    [JsonPropertyName("sortOrder")]
    public string SortOrder { get; set; } = "desc";

    [JsonPropertyName("filters")]
    public Dictionary<string, string> Filters { get; set; } = new();

    [JsonPropertyName("version")]
    public int Version { get; set; } = 1;

    [JsonPropertyName("expiresAt")]
    public DateTime ExpiresAt { get; set; }
}

// CursorPaginationRequest.cs (extends PaginationRequest)
public class CursorPaginationRequest : PaginationRequest
{
    [FromQuery(Name = "cursor")]
    public string? Cursor { get; set; }

    public bool IsCursorMode => !string.IsNullOrEmpty(Cursor);
}
```

**Step 2: Implement Cursor Service**

```csharp
// ICursorService.cs
public interface ICursorService
{
    string EncodeCursor(CursorToken token);
    CursorToken? DecodeCursor(string cursor);
    bool ValidateCursor(string cursor);
}

// JwtCursorService.cs
public class JwtCursorService : ICursorService
{
    private readonly string _signingKey;
    private readonly ILogger<JwtCursorService> _logger;

    public JwtCursorService(IOptions<PaginationOptions> options, ILogger<JwtCursorService> logger)
    {
        _signingKey = options.Value.CursorSigningKey;
        _logger = logger;
    }

    public string EncodeCursor(CursorToken token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.UTF8.GetBytes(_signingKey);

        var tokenDescriptor = new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(new[]
            {
                new Claim("lastId", token.LastId.ToString()),
                new Claim("lastValue", token.LastValue ?? string.Empty),
                new Claim("sortBy", token.SortBy),
                new Claim("sortOrder", token.SortOrder),
                new Claim("filters", JsonSerializer.Serialize(token.Filters)),
                new Claim("version", token.Version.ToString())
            }),
            Expires = token.ExpiresAt,
            SigningCredentials = new SigningCredentials(
                new SymmetricSecurityKey(key),
                SecurityAlgorithms.HmacSha256Signature)
        };

        var jwtToken = tokenHandler.CreateToken(tokenDescriptor);
        return tokenHandler.WriteToken(jwtToken);
    }

    public CursorToken? DecodeCursor(string cursor)
    {
        try
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            var key = Encoding.UTF8.GetBytes(_signingKey);

            tokenHandler.ValidateToken(cursor, new TokenValidationParameters
            {
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(key),
                ValidateIssuer = false,
                ValidateAudience = false,
                ClockSkew = TimeSpan.Zero
            }, out SecurityToken validatedToken);

            var jwtToken = (JwtSecurityToken)validatedToken;

            return new CursorToken
            {
                LastId = long.Parse(jwtToken.Claims.First(c => c.Type == "lastId").Value),
                LastValue = jwtToken.Claims.First(c => c.Type == "lastValue").Value,
                SortBy = jwtToken.Claims.First(c => c.Type == "sortBy").Value,
                SortOrder = jwtToken.Claims.First(c => c.Type == "sortOrder").Value,
                Filters = JsonSerializer.Deserialize<Dictionary<string, string>>(
                    jwtToken.Claims.First(c => c.Type == "filters").Value) ?? new(),
                Version = int.Parse(jwtToken.Claims.First(c => c.Type == "version").Value),
                ExpiresAt = jwtToken.ValidTo
            };
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Failed to decode cursor: {Cursor}", cursor);
            return null;
        }
    }

    public bool ValidateCursor(string cursor)
    {
        var token = DecodeCursor(cursor);
        return token != null && token.ExpiresAt > DateTime.UtcNow;
    }
}
```

**Step 3: Implement Cursor-Based Repository Method**

```csharp
// IClaimRepository.cs (add cursor method)
public interface IClaimRepository
{
    // Existing offset method
    Task<(List<ClaimDto> Items, long TotalCount)> GetClaimsAsync(
        string providerId,
        PaginationRequest pagination,
        CancellationToken cancellationToken = default);

    // New cursor method
    Task<(List<ClaimDto> Items, bool HasMore, CursorToken? NextCursor)> GetClaimsWithCursorAsync(
        string providerId,
        CursorPaginationRequest pagination,
        CursorToken? cursorToken,
        CancellationToken cancellationToken = default);
}

// ClaimRepository.cs
public async Task<(List<ClaimDto> Items, bool HasMore, CursorToken? NextCursor)> GetClaimsWithCursorAsync(
    string providerId,
    CursorPaginationRequest pagination,
    CursorToken? cursorToken,
    CancellationToken cancellationToken = default)
{
    var query = _context.Claims
        .Where(c => c.ProviderId == providerId)
        .AsNoTracking();

    // Apply cursor filter (keyset pagination)
    if (cursorToken != null)
    {
        if (cursorToken.SortOrder.ToLower() == "asc")
        {
            // For ascending order: (SubmittedDate > lastValue) OR (SubmittedDate = lastValue AND ClaimId > lastId)
            var lastDate = DateTime.Parse(cursorToken.LastValue!);
            query = query.Where(c =>
                c.SubmittedDate > lastDate ||
                (c.SubmittedDate == lastDate && c.ClaimId > cursorToken.LastId));
        }
        else
        {
            // For descending order: (SubmittedDate < lastValue) OR (SubmittedDate = lastValue AND ClaimId < lastId)
            var lastDate = DateTime.Parse(cursorToken.LastValue!);
            query = query.Where(c =>
                c.SubmittedDate < lastDate ||
                (c.SubmittedDate == lastDate && c.ClaimId < cursorToken.LastId));
        }
    }

    // Apply sorting (always include primary key for stable sort)
    query = pagination.SortOrder.ToLower() == "asc"
        ? query.OrderBy(c => c.SubmittedDate).ThenBy(c => c.ClaimId)
        : query.OrderByDescending(c => c.SubmittedDate).ThenByDescending(c => c.ClaimId);

    // Fetch pageSize + 1 to determine if more results exist
    var items = await query
        .Take(pagination.PageSize + 1)
        .Select(c => new ClaimDto
        {
            ClaimId = c.ClaimId,
            ProviderId = c.ProviderId,
            MemberId = c.MemberId,
            SubmittedDate = c.SubmittedDate,
            Amount = c.Amount,
            Status = c.Status
        })
        .ToListAsync(cancellationToken);

    // Check if more results exist
    var hasMore = items.Count > pagination.PageSize;

    // Remove extra record if present
    if (hasMore)
    {
        items.RemoveAt(items.Count - 1);
    }

    // Generate next cursor from last item
    CursorToken? nextCursor = null;
    if (hasMore && items.Count > 0)
    {
        var lastItem = items.Last();
        nextCursor = new CursorToken
        {
            LastId = lastItem.ClaimId,
            LastValue = lastItem.SubmittedDate.ToString("o"),
            SortBy = pagination.SortBy ?? "submittedDate",
            SortOrder = pagination.SortOrder,
            Filters = new Dictionary<string, string> { { "providerId", providerId } },
            Version = 1,
            ExpiresAt = DateTime.UtcNow.AddHours(1)
        };
    }

    return (items, hasMore, nextCursor);
}
```

**Step 4: Update Controller for Hybrid Pagination**

```csharp
[HttpGet]
public async Task<ActionResult<PaginatedResponse<ClaimDto>>> GetClaims(
    [FromQuery, Required] string providerId,
    [FromQuery] CursorPaginationRequest pagination,
    CancellationToken cancellationToken)
{
    try
    {
        if (pagination.IsCursorMode)
        {
            // Cursor-based pagination
            return await GetClaimsWithCursor(providerId, pagination, cancellationToken);
        }
        else
        {
            // Offset-based pagination (existing implementation)
            return await GetClaimsWithOffset(providerId, pagination, cancellationToken);
        }
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Error retrieving claims");
        return StatusCode(500, new ErrorResponse { /* ... */ });
    }
}

private async Task<ActionResult<PaginatedResponse<ClaimDto>>> GetClaimsWithCursor(
    string providerId,
    CursorPaginationRequest pagination,
    CancellationToken cancellationToken)
{
    // Decode cursor
    CursorToken? cursorToken = null;
    if (!string.IsNullOrEmpty(pagination.Cursor))
    {
        cursorToken = _cursorService.DecodeCursor(pagination.Cursor);
        if (cursorToken == null)
        {
            return BadRequest(new ErrorResponse
            {
                Error = new ErrorDetail
                {
                    Code = "INVALID_CURSOR",
                    Message = "The provided cursor is invalid or expired"
                }
            });
        }
    }

    // Fetch data
    var (items, hasMore, nextCursor) = await _repository.GetClaimsWithCursorAsync(
        providerId,
        pagination,
        cursorToken,
        cancellationToken);

    // Encode next cursor
    string? encodedCursor = nextCursor != null
        ? _cursorService.EncodeCursor(nextCursor)
        : null;

    // Build response (cursor mode - no total count)
    var response = new PaginatedResponse<ClaimDto>
    {
        Items = items,
        Pagination = new PaginationMetadata
        {
            PageSize = pagination.PageSize,
            HasMore = hasMore,
            Cursor = encodedCursor
        },
        Links = _linkGenerator.GenerateCursorLinks(
            Request.Path,
            Request.QueryString.ToString(),
            pagination.PageSize,
            encodedCursor),
        Meta = new ResponseMetadata
        {
            RequestId = HttpContext.TraceIdentifier,
            Timestamp = DateTime.UtcNow,
            ApiVersion = "v1"
        }
    };

    return Ok(response);
}

