#### Phase 3: Client Implementation

**JavaScript/TypeScript Client:**

```typescript
// paginationClient.ts
import axios, { AxiosInstance } from 'axios';

interface PaginationMetadata {
  page?: number;
  pageSize: number;
  totalRecords?: number;
  totalPages?: number;
  hasMore: boolean;
  cursor?: string;
}

interface Link {
  href: string;
}

interface PaginatedResponse<T> {
  items: T[];
  pagination: PaginationMetadata;
  _links: {
    self: Link;
    first: Link;
    last?: Link;
    next?: Link;
    previous?: Link;
  };
}

interface Claim {
  claimId: number;
  providerId: string;
  memberId: string;
  submittedDate: string;
  amount: number;
  status: string;
}

/**

 * Pagination client supporting both offset and cursor modes
 */
export class PaginationClient<T> {
  constructor(private httpClient: AxiosInstance) {}

  /**
   * Fetch first page (offset mode)
   */
  async fetchFirstPage(
    url: string,
    pageSize: number = 50,
    queryParams: Record<string, any> = {}
  ): Promise<PaginatedResponse<T>> {
    const response = await this.httpClient.get<PaginatedResponse<T>>(url, {
      params: { page: 1, pageSize, ...queryParams }
    });
    return response.data;
  }

  /**
   * Fetch specific page (offset mode)
   */
  async fetchPage(
    url: string,
    page: number,
    pageSize: number = 50,
    queryParams: Record<string, any> = {}
  ): Promise<PaginatedResponse<T>> {
    const response = await this.httpClient.get<PaginatedResponse<T>>(url, {
      params: { page, pageSize, ...queryParams }
    });
    return response.data;
  }

  /**
   * Fetch using cursor (cursor mode)
   */
  async fetchWithCursor(
    url: string,
    cursor?: string,
    pageSize: number = 50
  ): Promise<PaginatedResponse<T>> {
    const params: any = { pageSize };
    if (cursor) {
      params.cursor = cursor;
    }
    const response = await this.httpClient.get<PaginatedResponse<T>>(url, { params });
    return response.data;
  }

  /**
   * Fetch next page using HATEOAS link
   */
  async fetchNext(currentResponse: PaginatedResponse<T>): Promise<PaginatedResponse<T> | null> {
    if (!currentResponse._links.next) {
      return null; // No more pages
    }
    const response = await this.httpClient.get<PaginatedResponse<T>>(
      currentResponse._links.next.href
    );
    return response.data;
  }

  /**
   * Iterate through all pages (offset mode)
   */
  async *iterateAllPages(
    url: string,
    pageSize: number = 50,
    queryParams: Record<string, any> = {}
  ): AsyncGenerator<T[], void, unknown> {
    let page = 1;
    let hasMore = true;

    while (hasMore) {
      const response = await this.fetchPage(url, page, pageSize, queryParams);
      yield response.items;

      hasMore = response.pagination.hasMore;
      page++;
    }
  }

  /**
   * Iterate through all records using cursor (cursor mode - recommended for large datasets)
   */
  async *iterateWithCursor(
    url: string,
    pageSize: number = 1000
  ): AsyncGenerator<T[], void, unknown> {
    let cursor: string | undefined = undefined;
    let hasMore = true;

    while (hasMore) {
      const response = await this.fetchWithCursor(url, cursor, pageSize);
      yield response.items;

      hasMore = response.pagination.hasMore;
      cursor = response.pagination.cursor;
    }
  }

  /**
   * Fetch all records (use with caution - can be memory intensive)
   */
  async fetchAll(
    url: string,
    useCursor: boolean = true,
    pageSize: number = 1000
  ): Promise<T[]> {
    const allItems: T[] = [];

    if (useCursor) {
      for await (const items of this.iterateWithCursor(url, pageSize)) {
        allItems.push(...items);
      }
    } else {
      for await (const items of this.iterateAllPages(url, pageSize)) {
        allItems.push(...items);
      }
    }

    return allItems;
  }
}

// Usage Example 1: Interactive UI with offset pagination
async function displayProviderPortalClaims() {
  const client = new PaginationClient<Claim>(axios.create({ baseURL: 'https://api.gainwell.com' }));

  // Fetch first page
  const response = await client.fetchFirstPage('/api/v1/claims', 50, { providerId: '1234567890' });

  console.log(`Showing page ${response.pagination.page} of ${response.pagination.totalPages}`);
  console.log(`Total claims: ${response.pagination.totalRecords}`);

  // Display claims
  response.items.forEach(claim => {
    console.log(`Claim ${claim.claimId}: $${claim.amount} - ${claim.status}`);
  });

  // Fetch next page using HATEOAS link
  if (response._links.next) {
    const nextPage = await client.fetchNext(response);
    console.log(`Next page has ${nextPage?.items.length} claims`);
  }
}

// Usage Example 2: Batch export with cursor pagination
async function exportAllClaimsForReporting() {
  const client = new PaginationClient<Claim>(axios.create({ baseURL: 'https://api.gainwell.com' }));

  const allClaims: Claim[] = [];
  let pageCount = 0;

  // Iterate using cursor for consistency
  for await (const items of client.iterateWithCursor('/api/v1/claims?providerId=1234567890', 1000)) {
    allClaims.push(...items);
    pageCount++;
    console.log(`Fetched batch ${pageCount}: ${items.length} claims (total: ${allClaims.length})`);
  }

  console.log(`Export complete: ${allClaims.length} claims`);
  return allClaims;
}

// Usage Example 3: React Hook for pagination
import { useState, useEffect } from 'react';

function usePagination<T>(url: string, pageSize: number = 50) {
  const [data, setData] = useState<PaginatedResponse<T> | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const client = new PaginationClient<T>(axios.create({ baseURL: 'https://api.gainwell.com' }));

  const fetchPage = async (page: number) => {
    setLoading(true);
    setError(null);
    try {
      const response = await client.fetchPage(url, page, pageSize);
      setData(response);
    } catch (err) {
      setError(err as Error);
    } finally {
      setLoading(false);
    }
  };

  const fetchNext = async () => {
    if (!data?._links.next) return;
    setLoading(true);
    try {
      const response = await client.fetchNext(data);
      setData(response);
    } catch (err) {
      setError(err as Error);
    } finally {
      setLoading(false);
    }
  };

  const fetchPrevious = async () => {
    if (!data?._links.previous) return;
    setLoading(true);
    try {
      const response = await axios.get<PaginatedResponse<T>>(data._links.previous.href);
      setData(response.data);
    } catch (err) {
      setError(err as Error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPage(1);
  }, [url, pageSize]);

  return { data, loading, error, fetchPage, fetchNext, fetchPrevious };
}

// React Component Usage
function ClaimsList() {
  const { data, loading, error, fetchNext, fetchPrevious } = usePagination<Claim>(
    '/api/v1/claims?providerId=1234567890',
    50
  );

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;
  if (!data) return null;

  return (
    <div>
      <h2>Claims (Page {data.pagination.page} of {data.pagination.totalPages})</h2>
      <ul>
        {data.items.map(claim => (
          <li key={claim.claimId}>
            Claim {claim.claimId}: ${claim.amount} - {claim.status}
          </li>
        ))}
      </ul>
      <div>
        <button onClick={fetchPrevious} disabled={!data._links.previous}>Previous</button>
        <button onClick={fetchNext} disabled={!data._links.next}>Next</button>
      </div>
    </div>
  );
}
```

