{
    entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
    return await _context.Claims.Where(c => c.Status == status).CountAsync();
});
```

**Option B: Approximate Count**
```sql
-- Use table statistics for approximate count (instant)
SELECT SUM(rows)
FROM sys.partitions
WHERE object_id = OBJECT_ID('Claims') AND index_id IN (0,1);
```

**Option C: Omit Count in Cursor Mode**
```csharp
// Cursor mode doesn't need total count
if (pagination.IsCursorMode)
{
    response.Pagination.TotalRecords = null; // Omit expensive count
    response.Pagination.TotalPages = null;
}
