    var response = await _client.GetAsync("/api/v1/claims?page=1&pageSize=50");
    stopwatch.Stop();

    Assert.IsTrue(response.IsSuccessStatusCode);
    Assert.IsTrue(stopwatch.ElapsedMilliseconds < 200,
        $"First page took {stopwatch.ElapsedMilliseconds}ms (target: <200ms)");
