{
    var stopwatch = Stopwatch.StartNew();
    var response = await _client.GetAsync("/api/v1/claims?page=100&pageSize=50");
    stopwatch.Stop();

    Assert.IsTrue(response.IsSuccessStatusCode);
    Assert.IsTrue(stopwatch.ElapsedMilliseconds < 2000,
        $"Deep pagination took {stopwatch.ElapsedMilliseconds}ms (target: <2s)");
