[Test]
public async Task CursorPagination_ConsistentResults()
{
    // Fetch page 1
    var page1 = await _client.GetAsync("/api/v1/claims?pageSize=100");
    var page1Data = await page1.Content.ReadAsAsync<PaginatedResponse<Claim>>();

    // Insert new records (simulate data changes)
