        `/api/v1/claims?providerId=${providerId}&status=Paid&page=${page}&pageSize=50&sortBy=submittedDate&sortOrder=desc`
      );
      const data = await response.json();
      setClaims(data);
    } catch (error) {
      console.error("Error fetching claims:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPage(1);
  }, []);

  if (loading) return <Spinner />;
  if (!claims) return null;

  return (
    <div className="claims-list">
      <h2>Submitted Claims</h2>
      <p>Showing {claims.items.length} of {claims.pagination.totalRecords} claims</p>

      <table>
        <thead>
          <tr>
            <th>Claim ID</th>
            <th>Member</th>
            <th>Submitted Date</th>
            <th>Amount</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {claims.items.map(claim => (
            <tr key={claim.claimId}>
              <td>{claim.claimId}</td>
              <td>{claim.memberId}</td>
              <td>{new Date(claim.submittedDate).toLocaleDateString()}</td>
              <td>${claim.amount.toFixed(2)}</td>
              <td>{claim.status}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <Pagination
        currentPage={claims.pagination.page!}
        totalPages={claims.pagination.totalPages!}
        onPageChange={fetchPage}
        links={claims._links}
      />
    </div>
  );
}

function Pagination({ currentPage, totalPages, onPageChange, links }) {
  return (
    <div className="pagination">
      <button
        onClick={() => onPageChange(1)}
        disabled={!links.first || currentPage === 1}
      >
        First
      </button>

      <button
        onClick={() => onPageChange(currentPage - 1)}
        disabled={!links.previous}
      >
        Previous
      </button>

      <span>Page {currentPage} of {totalPages}</span>

      <button
        onClick={() => onPageChange(currentPage + 1)}
        disabled={!links.next}
      >
        Next
      </button>

      <button
        onClick={() => onPageChange(totalPages)}
        disabled={!links.last || currentPage === totalPages}
      >
        Last
      </button>
    </div>
  );
}
```

