### Example 4: FHIR API - Patient Resource Search

**Scenario:** Third-party EMR system searches for patients matching criteria via FHIR R4 API.

**Requirements:**
- FHIR Bundle pagination compliance
- Support `_count` parameter
- Continuation URLs for next/previous pages
- ONC Certification requirement

**Implementation:**

```csharp
// FhirPatientsController.cs
[ApiController]
[Route("fhir/Patient")]
public class FhirPatientsController : ControllerBase
{
    [HttpGet]
    [Produces("application/fhir+json")]
    public async Task<ActionResult<Bundle>> SearchPatients(
        [FromQuery(Name = "family")] string? familyName,
        [FromQuery(Name = "given")] string? givenName,
        [FromQuery(Name = "_count")] int count = 20,
        [FromQuery(Name = "_getpages")] string? cursor = null)
    {
        // Validate count
        if (count < 1 || count > 100)
        {
            return BadRequest(CreateOperationOutcome("Invalid _count parameter. Must be between 1 and 100."));
        }

        // Build query
        var query = _context.Patients.AsQueryable();
        if (!string.IsNullOrEmpty(familyName))
            query = query.Where(p => p.FamilyName.Contains(familyName));
        if (!string.IsNullOrEmpty(givenName))
            query = query.Where(p => p.GivenName.Contains(givenName));

        // Apply cursor pagination (FHIR uses cursor under the hood)
        CursorToken? cursorToken = null;
        if (!string.IsNullOrEmpty(cursor))
        {
            cursorToken = _cursorService.DecodeCursor(cursor);
            if (cursorToken == null)
                return BadRequest(CreateOperationOutcome("Invalid or expired continuation token."));
        }

        var (patients, hasMore, nextCursor) = await _repository.GetPatientsWithCursorAsync(
            query, count, cursorToken);

        // Build FHIR Bundle
        var bundle = new Bundle
        {
            Type = Bundle.BundleType.Searchset,
            Total = hasMore ? null : patients.Count, // Total omitted if more results exist (expensive to compute)
            Link = new List<Bundle.LinkComponent>()
        };

        // Self link
        var selfUrl = $"{Request.Scheme}://{Request.Host}/fhir/Patient?family={familyName}&given={givenName}&_count={count}";
        if (!string.IsNullOrEmpty(cursor))
            selfUrl += $"&_getpages={cursor}";
        bundle.Link.Add(new Bundle.LinkComponent { Relation = "self", Url = selfUrl });

        // Next link
        if (hasMore && nextCursor != null)
        {
            var encodedCursor = _cursorService.EncodeCursor(nextCursor);
            var nextUrl = $"{Request.Scheme}://{Request.Host}/fhir/Patient?family={familyName}&given={givenName}&_count={count}&_getpages={encodedCursor}";
            bundle.Link.Add(new Bundle.LinkComponent { Relation = "next", Url = nextUrl });
        }

        // Add entries
        foreach (var patient in patients)
        {
            bundle.Entry.Add(new Bundle.EntryComponent
            {
                FullUrl = $"{Request.Scheme}://{Request.Host}/fhir/Patient/{patient.Id}",
                Resource = patient.ToFhirResource()
            });
        }

        return Ok(bundle);
    }
}
```

